-- case: scatter_color
SELECT * FROM (SELECT * FROM pts) AS __schema__ LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "g" AS "__ggsql_aes_fill__", "a" AS "__ggsql_aes_pos1__", "b" AS "__ggsql_aes_pos2__", "g" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM pts) AS "__ggsql_src__") SELECT MIN("a") AS "a", MIN("b") AS "b", MIN("g") AS "g" FROM "__ggsql_source__" UNION ALL SELECT MAX("a") AS "a", MAX("b") AS "b", MAX("g") AS "g" FROM "__ggsql_source__";
SELECT *, "g" AS "__ggsql_aes_fill__", "a" AS "__ggsql_aes_pos1__", "b" AS "__ggsql_aes_pos2__", "g" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM pts) AS "__ggsql_src__";

-- case: histogram
SELECT * FROM (SELECT * FROM hist_data) AS __schema__ LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "value" AS "__ggsql_aes_pos1__" FROM (SELECT * FROM hist_data) AS "__ggsql_src__") SELECT MIN("value") AS "value" FROM "__ggsql_source__" UNION ALL SELECT MAX("value") AS "value" FROM "__ggsql_source__";
SELECT MIN("__ggsql_aes_pos1__") as min_val, MAX("__ggsql_aes_pos1__") as max_val FROM (SELECT *, "value" AS "__ggsql_aes_pos1__" FROM (SELECT * FROM hist_data) AS "__ggsql_src__") AS "__ggsql_stats__";
SELECT *, "__ggsql_stat_bin" AS "__ggsql_aes_pos1__", "__ggsql_stat_bin_end" AS "__ggsql_aes_pos1end__", "__ggsql_stat_count" AS "__ggsql_aes_pos2__" FROM (WITH "__stat_src__" AS (SELECT *, "value" AS "__ggsql_aes_pos1__" FROM (SELECT * FROM hist_data) AS "__ggsql_src__"), "__binned__" AS (SELECT ((CASE WHEN (0) >= (CEIL(("__ggsql_aes_pos1__" - 1 + 1 * 0.5) / 1) - 1) THEN (0) ELSE (CEIL(("__ggsql_aes_pos1__" - 1 + 1 * 0.5) / 1) - 1) END)) * 1 + 1 - 1 * 0.5 AS "__ggsql_stat_bin", COUNT(*) AS "__ggsql_stat_count" FROM "__stat_src__" GROUP BY ((CASE WHEN (0) >= (CEIL(("__ggsql_aes_pos1__" - 1 + 1 * 0.5) / 1) - 1) THEN (0) ELSE (CEIL(("__ggsql_aes_pos1__" - 1 + 1 * 0.5) / 1) - 1) END)) * 1 + 1 - 1 * 0.5) SELECT *, "__ggsql_stat_bin" + 1 AS "__ggsql_stat_bin_end", "__ggsql_stat_count" * 1.0 / SUM("__ggsql_stat_count") OVER () AS "__ggsql_stat_density" FROM "__binned__") AS "__ggsql_stat__";

-- case: boxplot_grouped
SELECT * FROM (SELECT * FROM box_data) AS __schema__ LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") SELECT MIN("grp") AS "grp", MIN("value") AS "value" FROM "__ggsql_source__" UNION ALL SELECT MAX("grp") AS "grp", MAX("value") AS "value" FROM "__ggsql_source__";
SELECT *, "__ggsql_stat_type" AS "__ggsql_aes_type__", "__ggsql_stat_value" AS "__ggsql_aes_pos2__", "__ggsql_stat_value2" AS "__ggsql_aes_pos2end__" FROM (WITH summary AS ( SELECT *, (CASE WHEN (q1 - 1.5 * (q3 - q1)) >= (min) THEN (q1 - 1.5 * (q3 - q1)) ELSE (min) END) AS lower, (CASE WHEN (q3 + 1.5 * (q3 - q1)) <= (max) THEN (q3 + 1.5 * (q3 - q1)) ELSE (max) END) AS upper FROM ( SELECT "__ggsql_aes_pos1__", MIN("__ggsql_aes_pos2__") AS min, MAX("__ggsql_aes_pos2__") AS max, (SELECT (MAX(CASE WHEN __tile = 1 THEN __val END) + MIN(CASE WHEN __tile = 2 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos2__" AS __val, NTILE(4) OVER (ORDER BY "__ggsql_aes_pos2__") AS __tile FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos2__" IS NOT NULL AND "__ggsql_pct__"."__ggsql_aes_pos1__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_pos1__") AS "__ggsql_tile__") AS q1, (SELECT (MAX(CASE WHEN __tile = 2 THEN __val END) + MIN(CASE WHEN __tile = 3 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos2__" AS __val, NTILE(4) OVER (ORDER BY "__ggsql_aes_pos2__") AS __tile FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos2__" IS NOT NULL AND "__ggsql_pct__"."__ggsql_aes_pos1__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_pos1__") AS "__ggsql_tile__") AS median, (SELECT (MAX(CASE WHEN __tile = 3 THEN __val END) + MIN(CASE WHEN __tile = 4 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos2__" AS __val, NTILE(4) OVER (ORDER BY "__ggsql_aes_pos2__") AS __tile FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos2__" IS NOT NULL AND "__ggsql_pct__"."__ggsql_aes_pos1__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_pos1__") AS "__ggsql_tile__") AS q3 FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "__ggsql_qt__" WHERE "__ggsql_aes_pos2__" IS NOT NULL GROUP BY "__ggsql_aes_pos1__" ) AS "__ggsql_fn__" ), outliers AS ( SELECT raw."__ggsql_aes_pos2__" AS value, 'outlier' AS type, raw."__ggsql_aes_pos1__" AS "__ggsql_aes_pos1__" FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") raw JOIN summary ON raw."__ggsql_aes_pos1__" = summary."__ggsql_aes_pos1__" WHERE raw."__ggsql_aes_pos2__" NOT BETWEEN summary.lower AND summary.upper ) SELECT "__ggsql_aes_pos1__", 'lower_whisker' AS "__ggsql_stat_type", q1 AS "__ggsql_stat_value", lower AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", 'upper_whisker' AS "__ggsql_stat_type", q3 AS "__ggsql_stat_value", upper AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", 'box' AS "__ggsql_stat_type", q1 AS "__ggsql_stat_value", q3 AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", 'median' AS "__ggsql_stat_type", median AS "__ggsql_stat_value", NULL AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", type AS "__ggsql_stat_type", value AS "__ggsql_stat_value", NULL AS "__ggsql_stat_value2" FROM outliers ) AS "__ggsql_stat__";

-- case: density_grouped
SELECT * FROM (SELECT * FROM dens_data) AS __schema__ LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") SELECT MIN("value") AS "value", MIN("grp") AS "grp" FROM "__ggsql_source__" UNION ALL SELECT MAX("value") AS "value", MAX("grp") AS "grp" FROM "__ggsql_source__";
SELECT *, "__ggsql_stat_pos1" AS "__ggsql_aes_pos1__", "__ggsql_stat_density" AS "__ggsql_aes_pos2__" FROM (WITH RECURSIVE bandwidth AS ( SELECT 0.9 * (CASE WHEN (SQRT(AVG("__ggsql_aes_pos1__"*"__ggsql_aes_pos1__") - AVG("__ggsql_aes_pos1__")*AVG("__ggsql_aes_pos1__"))) <= (((SELECT (MAX(CASE WHEN __tile = 3 THEN __val END) + MIN(CASE WHEN __tile = 4 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos1__" AS __val, NTILE(4) OVER (ORDER BY "__ggsql_aes_pos1__") AS __tile FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL AND "__ggsql_pct__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__" AND "__ggsql_pct__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__") AS "__ggsql_tile__") - (SELECT (MAX(CASE WHEN __tile = 1 THEN __val END) + MIN(CASE WHEN __tile = 2 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos1__" AS __val, NTILE(4) OVER (ORDER BY "__ggsql_aes_pos1__") AS __tile FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL AND "__ggsql_pct__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__" AND "__ggsql_pct__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__") AS "__ggsql_tile__")) / 1.34) THEN (SQRT(AVG("__ggsql_aes_pos1__"*"__ggsql_aes_pos1__") - AVG("__ggsql_aes_pos1__")*AVG("__ggsql_aes_pos1__"))) ELSE (((SELECT (MAX(CASE WHEN __tile = 3 THEN __val END) + MIN(CASE WHEN __tile = 4 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos1__" AS __val, NTILE(4) OVER (ORDER BY "__ggsql_aes_pos1__") AS __tile FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL AND "__ggsql_pct__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__" AND "__ggsql_pct__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__") AS "__ggsql_tile__") - (SELECT (MAX(CASE WHEN __tile = 1 THEN __val END) + MIN(CASE WHEN __tile = 2 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos1__" AS __val, NTILE(4) OVER (ORDER BY "__ggsql_aes_pos1__") AS __tile FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL AND "__ggsql_pct__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__" AND "__ggsql_pct__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__") AS "__ggsql_tile__")) / 1.34) END) * POW(COUNT(*), -0.2) AS bw, "__ggsql_aes_fill__", "__ggsql_aes_stroke__", MIN("__ggsql_aes_pos1__") AS x_min, MAX("__ggsql_aes_pos1__") AS x_max FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_qt__" WHERE "__ggsql_aes_pos1__" IS NOT NULL GROUP BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ), data AS ( SELECT "__ggsql_aes_fill__", "__ggsql_aes_stroke__", "__ggsql_aes_pos1__" AS val, 1.0 AS weight FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_data__" WHERE "__ggsql_aes_pos1__" IS NOT NULL ), "__ggsql_seq__"(n) AS (SELECT CAST(generate_series AS DOUBLE) AS n FROM generate_series(0, 512 - 1)), global_range AS ( SELECT MIN(x_min) AS min, MAX(x_max) AS max, 3 * MAX(bw) AS expansion FROM bandwidth ), grid AS ( SELECT "__ggsql_aes_fill__", "__ggsql_aes_stroke__", ("__ggsql_global__".min - "__ggsql_global__".expansion) + (seq.n * (("__ggsql_global__".max - "__ggsql_global__".min) + 2 * "__ggsql_global__".expansion) / 511) AS x FROM global_range AS "__ggsql_global__" CROSS JOIN "__ggsql_seq__" AS seq CROSS JOIN (SELECT DISTINCT "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM bandwidth) AS "__ggsql_groups__" ) SELECT "__ggsql_stat_pos1", "__ggsql_aes_fill__", "__ggsql_aes_stroke__", "__ggsql_stat_intensity", "__ggsql_stat_intensity" / "__norm" AS "__ggsql_stat_density" FROM ( SELECT grid.x AS "__ggsql_stat_pos1", grid."__ggsql_aes_fill__" AS "__ggsql_aes_fill__", grid."__ggsql_aes_stroke__" AS "__ggsql_aes_stroke__", SUM(data.weight * ((EXP(-0.5 * (grid.x - data.val) * (grid.x - data.val) / (bandwidth.bw * bandwidth.bw))) * 0.3989422804014327)) / MIN(bandwidth.bw) AS "__ggsql_stat_intensity", SUM(data.weight) AS "__norm" FROM data INNER JOIN bandwidth ON data."__ggsql_aes_fill__" IS NOT DISTINCT FROM bandwidth."__ggsql_aes_fill__" AND data."__ggsql_aes_stroke__" IS NOT DISTINCT FROM bandwidth."__ggsql_aes_stroke__" INNER JOIN grid ON grid."__ggsql_aes_fill__" IS NOT DISTINCT FROM data."__ggsql_aes_fill__" AND grid."__ggsql_aes_stroke__" IS NOT DISTINCT FROM data."__ggsql_aes_stroke__" GROUP BY grid.x, grid."__ggsql_aes_fill__", grid."__ggsql_aes_stroke__" ORDER BY grid.x, grid."__ggsql_aes_fill__", grid."__ggsql_aes_stroke__" ) AS "__ggsql_kde__") AS "__ggsql_stat__";

-- case: line_temporal
DROP TABLE IF EXISTS "__ggsql_global_<session>__";
CREATE TEMP TABLE "__ggsql_global_<session>__" AS SELECT * FROM ts_data;
SELECT * FROM (SELECT * FROM "__ggsql_global_<session>__") AS __schema__ LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "day" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM "__ggsql_global_<session>__") AS "__ggsql_src__") SELECT MIN("day") AS "day", MIN("value") AS "value", MIN("__ggsql_global_<session>__") AS "__ggsql_global_<session>__" FROM "__ggsql_source__" UNION ALL SELECT MAX("day") AS "day", MAX("value") AS "value", MAX("__ggsql_global_<session>__") AS "__ggsql_global_<session>__" FROM "__ggsql_source__";
SELECT *, "day" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM "__ggsql_global_<session>__") AS "__ggsql_src__" ORDER BY "__ggsql_aes_pos1__";

-- case: bar_count
SELECT * FROM (SELECT * FROM bar_data) AS __schema__ LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "category" AS "__ggsql_aes_pos1__" FROM (SELECT * FROM bar_data) AS "__ggsql_src__") SELECT MIN("category") AS "category" FROM "__ggsql_source__" UNION ALL SELECT MAX("category") AS "category" FROM "__ggsql_source__";
SELECT *, "__ggsql_stat_count" AS "__ggsql_aes_pos2__" FROM (WITH "__stat_src__" AS (SELECT *, "category" AS "__ggsql_aes_pos1__" FROM (SELECT * FROM bar_data) AS "__ggsql_src__"), "__grouped__" AS (SELECT "__ggsql_aes_pos1__", COUNT(*) AS "__ggsql_stat_count" FROM "__stat_src__" GROUP BY "__ggsql_aes_pos1__") SELECT *, "__ggsql_stat_count" * 1.0 / SUM("__ggsql_stat_count") OVER () AS "__ggsql_stat_proportion" FROM "__grouped__") AS "__ggsql_stat__";

-- case: filter_layer
DROP TABLE IF EXISTS "__ggsql_global_<session>__";
CREATE TEMP TABLE "__ggsql_global_<session>__" AS SELECT * FROM pts;
SELECT * FROM (SELECT * FROM "__ggsql_global_<session>__") AS __schema__ LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "a" AS "__ggsql_aes_pos1__", "b" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM "__ggsql_global_<session>__") AS "__ggsql_src__" WHERE g = 'A') SELECT MIN("a") AS "a", MIN("b") AS "b", MIN("g") AS "g", MIN("__ggsql_global_<session>__") AS "__ggsql_global_<session>__" FROM "__ggsql_source__" UNION ALL SELECT MAX("a") AS "a", MAX("b") AS "b", MAX("g") AS "g", MAX("__ggsql_global_<session>__") AS "__ggsql_global_<session>__" FROM "__ggsql_source__";
SELECT *, "a" AS "__ggsql_aes_pos1__", "b" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM "__ggsql_global_<session>__") AS "__ggsql_src__" WHERE g = 'A';

